 CREATE OR REPLACE FUNCTION public.getassessmentdetailsbytitleheadertext(assessmentdetails json, intakeserviceid uuid, roletypecode character varying)                                                                     
  RETURNS TABLE(assessmentid uuid, assessmenttemplateid uuid, external_templateid character varying, submissionid character varying, submissiondata json, titleheadertext text, assessmentdate timestamp without time zone)
  LANGUAGE plpgsql                                                                                                                                                                                                         
 AS $function$                                                                                                                                                                                                             
                                                                                                                                                                                                                           
 declare                                                                                                                                                                                                                   
 v_intakeserviceid uuid;                                                                                                                                                                                                   
 v_titleheadertext text;                                                                                                                                                                                                   
 v_assessmenttemplateid uuid;                                                                                                                                                                                              
 a_assessmentid uuid;                                                                                                                                                                                                      
 a_assessmenttemplateid uuid;                                                                                                                                                                                              
 a_external_templateid character varying;                                                                                                                                                                                  
 a_submissionid character varying;                                                                                                                                                                                         
 a_submissiondata json;                                                                                                                                                                                                    
 a_titleheadertext text;                                                                                                                                                                                                   
 l_details json;                                                                                                                                                                                                           
 v_roletypecode character varying;                                                                                                                                                                                         
 v_insertedon timestamp without time zone;                                                                                                                                                                                 
 i json;                                                                                                                                                                                                                   
  BEGIN                                                                                                                                                                                                                    
   v_intakeserviceid := intakeserviceid;                                                                                                                                                                                   
   v_roletypecode :=roletypecode;                                                                                                                                                                                          
                                                                                                                                                                                                                           
   CREATE temp TABLE sp_createassessment_temp_assessment1                                                                                                                                                                  
   (                                                                                                                                                                                                                       
      assessmentid uuid,                                                                                                                                                                                                   
      assessmenttemplateid   uuid,                                                                                                                                                                                         
         external_templateid character varying,                                                                                                                                                                            
      submissionid      character varying,                                                                                                                                                                                 
      submissiondata json,                                                                                                                                                                                                 
          titleheadertext text,                                                                                                                                                                                            
          assessmentdate timestamp without time zone                                                                                                                                                                       
                                                                                                                                                                                                                           
   );                                                                                                                                                                                                                      
  FOR i IN SELECT * FROM json_array_elements(assessmentdetails)                                                                                                                                                            
             LOOP                                                                                                                                                                                                          
                         select i->>'titleheadertext' into v_titleheadertext;                                                                                                                                              
                         RAISE NOTICE ' titleheadertext %',v_titleheadertext;                                                                                                                                              
                                                                                                                                                                                                                           
     INSERT INTO sp_createassessment_temp_assessment1                                                                                                                                                                      
                (                                                                                                                                                                                                          
                 assessmentid,                                                                                                                                                                                             
                                 assessmenttemplateid ,                                                                                                                                                                    
                                 external_templateid  ,                                                                                                                                                                    
                 submissionid ,                                                                                                                                                                                            
                                 submissiondata,                                                                                                                                                                           
                                 titleheadertext,                                                                                                                                                                          
                                 assessmentdate                                                                                                                                                                            
                                                                                                                                                                                                                           
                 )                                                                                                                                                                                                         
         select asm.assessmentid,                                                                                                                                                                                          
                                 ast.assessmenttemplateid ,                                                                                                                                                                
                                 ast.external_templateid  ,                                                                                                                                                                
                 asm.submissionid ,                                                                                                                                                                                        
                                 asm.submissiondata,                                                                                                                                                                       
                                 ast.titleheadertext,                                                                                                                                                                      
                                 asm.insertedon as assessmentdate                                                                                                                                                          
 from assessment asm join assessmenttemplate ast on ast.assessmenttemplateid = asm.assessmenttemplateid                                                                                                                    
 where ast.titleheadertext = v_titleheadertext                                                                                                                                                                             
  and asm.objectid = v_intakeserviceid and asm.activeflag = 1 and ast.activeflag = 1                                                                                                                                       
  order by asm.insertedon desc limit 1;                                                                                                                                                                                    
                                                                                                                                                                                                                           
             END LOOP;                                                                                                                                                                                                     
                                                                                                                                                                                                                           
         RETURN Query                                                                                                                                                                                                      
         select  AST.assessmentid as assessmentid,                                                                                                                                                                         
          AST.assessmenttemplateid as assessmenttemplateid,                                                                                                                                                                
      AST.external_templateid as external_templateid,                                                                                                                                                                      
     AST.submissionid as submissionid,                                                                                                                                                                                     
      AST.submissiondata as submissiondata,                                                                                                                                                                                
     AST.titleheadertext as titleheadertext,                                                                                                                                                                               
     AST.assessmentdate as assessmentdate                                                                                                                                                                                  
     from sp_createassessment_temp_assessment1 AST order by AST.assessmentdate desc;                                                                                                                                       
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
    drop table sp_createassessment_temp_assessment1;                                                                                                                                                                       
   END;                                                                                                                                                                                                                    
                                                                                                                                                                                                                           
                                                                                                                                                                                                                           
 $function$                                                                                                                                                                                                                

